// Native guard regression runner. unlinkat is replaced with a recording no-op.
// All filesystem fixtures are generated by native-trash-guard.ts and preserved.
#import <Foundation/Foundation.h>
#import <AppKit/AppKit.h>
#include <node_api.h>
#include <sys/stat.h>
#include <pwd.h>
#include <unistd.h>
#include <fcntl.h>
#include <limits.h>
#include <algorithm>
#include <string>
#include <cstring>
#include <cassert>
#include <functional>

static std::string fixtureHome;
static uid_t fixtureUID = ::getuid();
static unsigned recordedRemovals = 0, checks = 0;
static passwd* fixtureUser(uid_t) {
  static passwd user{};
  user.pw_dir = const_cast<char*>(fixtureHome.c_str());
  return &user;
}
static uid_t fixtureUserID() { return fixtureUID; }
static int recordRemoval(int fd, const char* name, int flags) {
  char parent[PATH_MAX];
  assert(fcntl(fd, F_GETPATH, parent) == 0);
  const std::string root = fixtureHome + "/.Trash";
  assert(std::string(parent) == root || std::string(parent).rfind(root + "/", 0) == 0);
  assert(name && !std::strchr(name, '/') && std::strcmp(name, ".") && std::strcmp(name, ".."));
  assert(flags == 0 || flags == AT_REMOVEDIR);
  ++recordedRemovals;
  return 0; // Intentionally preserve the actual item.
}
#define VIEWER_TRASH_GUARD_TESTS 1
#define getpwuid fixtureUser
#define getuid fixtureUserID
#define unlinkat recordRemoval
#include "trash-ui.h"
#undef getpwuid
#undef getuid
#undef unlinkat

static void reject(std::function<void()> work) {
  const unsigned before = recordedRemovals;
  bool rejected = false;
  try { work(); } catch (const std::exception&) { rejected = true; }
  assert(rejected && before == recordedRemovals);
  ++checks;
}
static NSArray* request(NSString* file) {
  viewer_trash::FD directory(open(file.fileSystemRepresentation, O_RDONLY | O_DIRECTORY));
  struct stat root{}; assert(fstat(directory.value, &root) == 0);
  NSMutableArray* items = [NSMutableArray array];
  for (const auto& name : viewer_trash::names(directory.value, true)) {
    const auto item = viewer_trash::info(directory.value, name);
    [items addObject:@{@"name": [NSString stringWithUTF8String:name.c_str()],
      @"identity": [NSString stringWithUTF8String:viewer_trash::identifier(item).c_str()],
      @"size": @(item.st_size), @"modified": @(item.st_mtimespec.tv_sec * 1000.0 + item.st_mtimespec.tv_nsec / 1000000.0)}];
  }
  return @[@{@"path": file, @"identity": [NSString stringWithUTF8String:viewer_trash::identifier(root).c_str()], @"items": items}];
}
int main(int argc, char** argv) {
  @autoreleasepool {
    assert(argc == 2);
    fixtureHome = argv[1];
    NSString* trash = [NSString stringWithUTF8String:(fixtureHome + "/.Trash").c_str()];
    const auto reviewed = request(trash);
    auto roots = viewer_trash::review(reviewed);
    assert(roots.size() == 1 && roots[0].children.size() == 3); ++checks;
    auto& root = roots[0];
    const auto leaf = *std::find_if(root.children.begin(), root.children.end(), [](const auto& n){return n.name == "Notes.txt";});
    const auto link = *std::find_if(root.children.begin(), root.children.end(), [](const auto& n){return n.name == "Documents link";});
    assert(S_ISLNK(link.version.st_mode) && link.children.empty()); ++checks;
    viewer_trash::remove(root, root.fd->value, leaf);
    viewer_trash::remove(root, root.fd->value, link);
    assert(recordedRemovals == 2 && access((root.path + "/Notes.txt").c_str(), F_OK) == 0); ++checks;
    auto changed = leaf; changed.version.st_ino++;
    reject([&]{viewer_trash::remove(root, root.fd->value, changed);});
    changed = leaf; changed.version.st_ctimespec.tv_nsec++;
    reject([&]{viewer_trash::unchanged(root.fd->value, changed);});
    changed = leaf; changed.version.st_size++;
    reject([&]{viewer_trash::unchanged(root.fd->value, changed);});
    changed = leaf; changed.version.st_dev++;
    reject([&]{viewer_trash::remove(root, root.fd->value, changed);});
    NSMutableDictionary* forged = [reviewed[0] mutableCopy];
    forged[@"path"] = [NSString stringWithUTF8String:fixtureHome.c_str()];
    reject([&]{viewer_trash::review(@[forged]);});
    forged = [reviewed[0] mutableCopy]; forged[@"items"] = @[];
    reject([&]{viewer_trash::review(@[forged]);});
    forged = [reviewed[0] mutableCopy]; forged[@"identity"] = @"wrong-root";
    reject([&]{viewer_trash::review(@[forged]);});
    ++fixtureUID;
    reject([&]{viewer_trash::review(reviewed);});
    --fixtureUID;
    const auto nested = *std::find_if(root.children.begin(), root.children.end(), [](const auto& n){return n.name == "Nested";});
    viewer_trash::FD folder(openat(root.fd->value, "Nested", O_RDONLY | O_DIRECTORY | O_NOFOLLOW));
    // Moving an owned generated fixture is reversible. Its bytes stay preserved.
    assert(rename((root.path + "/Nested").c_str(), (fixtureHome + "/MovedOutsideTrash").c_str()) == 0);
    reject([&]{viewer_trash::stillInside(root, folder.value);});
    reject([&]{viewer_trash::remove(root, root.fd->value, nested);});
    printf("PASS %u native guard checks; %u removal calls recorded as no-ops. Fixtures preserved.\n", checks, recordedRemovals);
  }
}
